def Convert(infile, outfile):
    print("Converting " + infile.name + " => " + outfile.name)
    lines = infile.read().split('\n')
    state = 'start'
    lineno = 0
    dvh_count = 0
    data = []
    patient_id = None
    patient_name = None
    organ = None
    resolution = None
    bins = None
    date = None
    datarows = []
    # Parse input:
    for line in lines:
        lineno += 1
        if not line:  # skip empty lines.
            continue
        elif "XiO Dose Volume Histogram" == line:
            if state != 'start':
                elem = {'organ': organ, 'resolution': resolution, 'bins': bins,
                        'datarows': datarows}
                data.append(elem)
            state = 'new_dvh'
            dvh_count += 1
            organ = None
            resolution = None
            bins = None
            datarows = []
        elif state == 'new_dvh':
            state = 'got_id'
            if patient_id is None:
                patient_id = line
            else:
                if line != patient_id:
                    raise Exception("Error: Patient ID different in " + str(infile.name) \
                                    + ":" + str(lineno) + ", found: " + line)
        elif state == 'got_id':
            state = 'got_name'
            patient_name = line
            if patient_name is None:
                patient_name = line
            else:
                if line != patient_name:
                    raise Exception("Error: Patient name different in " + str(infile.name) \
                                    + ":" + str(lineno) + ", found: " + line)
        elif state == 'got_name':
            state = 'got_organ'
            organ = line
        elif state == 'got_organ':
            state = 'got_res'
            fields = line.split('\t')
